  // Status lifecycle order (for reference when building history chains)
  const LIFECYCLE = [
    'Booking Confirmed',
    'Documentation Submitted',
    'Gated In (Origin)',
    'Loaded on Vessel',
    'Departed Origin Port',
    'At Sea',
    'Arrived Destination Port',
    'Customs Cleared',
    'Available for Pickup',
    'Delivered',
  ];

  function buildHistory(
    bookingId: number,
    upToStatus: string,
    startOffset: number,  // days from base date
    portName: string,
    portLat: number,
    portLng: number,
    destPortName: string,
    destLat: number,
    destLng: number
  ): void {
    const idx = LIFECYCLE.indexOf(upToStatus);
    for (let i = 0; i <= idx; i++) {
      const status = LIFECYCLE[i];
      let locName: string;
      let lat: number;
      let lng: number;
      if (i < 3) {
        locName = portName;
        lat = portLat;
        lng = portLng;
      } else if (i >= 6) {
        locName = destPortName;
        lat = destLat;
        lng = destLng;
      } else {
        locName = 'At Sea';
        lat = (portLat + destLat) / 2;
        lng = (portLng + destLng) / 2;
      }
      insertStatusHistory.run({
        booking_id: bookingId,
        status,
        timestamp: isoDate(startOffset + i * 2),
        location_name: locName,
        latitude: lat,
        longitude: lng,
      });
    }
  }

