        const pings = buildGpsPings(
          bookingId,
          b.container_number,
          waypoints,
          fractionComplete,
          isoDate(-14),
          durationHours,
          status
        );
        for (const ping of pings) {
          insertGpsPing.run(ping);
        }
      }
    }
  });

  insertAll();
  console.log(`  ✓ Inserted ${bookings.length} bookings with status history and GPS pings`);
  console.log('🌱  Seed complete!');
