import { Router, Request, Response } from 'express';
import { db } from '../db/database';

const router = Router();

// GET /api/voyages  — list all voyages, optional ?route= filter
router.get('/', (req: Request, res: Response) => {
  const { route } = req.query;
  let query = 'SELECT * FROM voyages';
  const params: string[] = [];
  if (typeof route === 'string' && route) {
    query += ' WHERE route = ?';
    params.push(route);
  }
  query += ' ORDER BY etd ASC';
  const rows = db.prepare(query).all(...params);
  res.json(rows);
});

// GET /api/voyages/:id — single voyage detail
router.get('/:id', (req: Request, res: Response) => {
  const voyage = db
    .prepare('SELECT * FROM voyages WHERE id = ?')
    .get(req.params.id);
  if (!voyage) {
    res.status(404).json({ error: 'Voyage not found' });
    return;
  }
  res.json(voyage);
});

export default router;

import { Router, Request, Response } from 'express';
import { db } from '../db/database';

const router = Router();

// GET /api/map/containers
// Returns current position + metadata for all non-cancelled bookings.
// Position logic:
//   - If booking has GPS pings (At Sea / in-transit), use latest ping.
//   - Otherwise use origin port coords (not yet departed) or dest port coords (Delivered/Available for Pickup).
router.get('/containers', (_req: Request, res: Response) => {
  const AT_DEST_STATUSES = new Set([
    'Arrived Destination Port',
    'Customs Cleared',
    'Available for Pickup',
    'Delivered',
  ]);

  const bookings = db.prepare(`
    SELECT
      b.id, b.booking_number, b.container_number, b.container_type,
      b.cargo_description, b.hazmat, b.current_status, b.route,
      v.origin_port, v.origin_lat, v.origin_lng,
      v.destination_port, v.dest_lat, v.dest_lng,
      v.vessel_name, v.voyage_number
    FROM bookings b
    JOIN voyages v ON v.id = b.voyage_id
    WHERE b.current_status != 'Cancelled'
  `).all() as any[];

  const result = bookings.map((b) => {
    // Latest GPS ping
    const latestPing = db.prepare(`
      SELECT latitude, longitude, timestamp, status_at_ping
      FROM gps_pings
      WHERE booking_id = ?
      ORDER BY timestamp DESC
      LIMIT 1
    `).get(b.id) as any;

    let lat: number;
    let lng: number;
    let positionSource: string;

    if (latestPing) {
      lat = latestPing.latitude;
      lng = latestPing.longitude;
      positionSource = 'gps';
    } else if (AT_DEST_STATUSES.has(b.current_status)) {
      lat = b.dest_lat;
      lng = b.dest_lng;
      positionSource = 'destination_port';
    } else {
      lat = b.origin_lat;
      lng = b.origin_lng;
      positionSource = 'origin_port';
    }

    return {
      id: b.id,
      booking_number: b.booking_number,
      container_number: b.container_number,
      container_type: b.container_type,
      cargo_description: b.cargo_description,
      hazmat: b.hazmat === 1,
      current_status: b.current_status,
      route: b.route,
      vessel_name: b.vessel_name,
      voyage_number: b.voyage_number,
      origin_port: b.origin_port,
      origin_lat: b.origin_lat,
      origin_lng: b.origin_lng,
      destination_port: b.destination_port,
      dest_lat: b.dest_lat,
      dest_lng: b.dest_lng,
      position: { lat, lng },
      position_source: positionSource,
    };
  });

  res.json(result);
});

export default router;

import { Router, Request, Response } from 'express';
import { db } from '../db/database';

const router = Router();

// GET /api/dashboard
// Returns: counts by status, hazmat vs non-hazmat counts, upcoming voyages (ETD within next 30 days)
router.get('/', (_req: Request, res: Response) => {
  // Counts by status
  const statusCounts = db.prepare(`
    SELECT current_status AS status, COUNT(*) AS count
    FROM bookings
    GROUP BY current_status
  `).all() as { status: string; count: number }[];

  // Hazmat counts
  const hazmatRow = db.prepare(`
    SELECT
      SUM(CASE WHEN hazmat = 1 THEN 1 ELSE 0 END)    AS hazmat_count,
      SUM(CASE WHEN hazmat = 0 THEN 1 ELSE 0 END)    AS non_hazmat_count,
      COUNT(*)                                         AS total_count
    FROM bookings
  `).get() as { hazmat_count: number; non_hazmat_count: number; total_count: number };

  // Upcoming voyages: ETD within the next 30 days from now
  const now = new Date().toISOString();
  const in30 = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
  const upcomingVoyages = db.prepare(`
    SELECT
      id, voyage_number, vessel_name, route,
      origin_port, destination_port,
      etd, eta, capacity, available_slots, status
    FROM voyages
    WHERE etd >= ? AND etd <= ?
    ORDER BY etd ASC
  `).all(now, in30);

  res.json({
    status_counts: statusCounts,
    hazmat_summary: {
      hazmat: hazmatRow.hazmat_count ?? 0,
      non_hazmat: hazmatRow.non_hazmat_count ?? 0,
      total: hazmatRow.total_count ?? 0,
    },
    upcoming_voyages: upcomingVoyages,
  });
});

export default router;

