+    FROM bookings b
+    JOIN voyages v ON v.id = b.voyage_id
+    WHERE 1=1
+  `;
+  const params: any[] = [];
+
+  if (typeof route === 'string' && route) {
+    query += ' AND b.route = ?';
+    params.push(route);
+  }
+  if (typeof status === 'string' && status) {
+    query += ' AND b.current_status = ?';
+    params.push(status);
+  }
+  if (typeof hazmat === 'string' && hazmat !== '') {
+    query += ' AND b.hazmat = ?';
+    params.push(hazmat === 'true' || hazmat === '1' ? 1 : 0);
