+    voyage.origin_lat,
+    voyage.origin_lng,
+  );
+
+  // Return one available slot to voyage
+  db.prepare(`
+    UPDATE voyages SET available_slots = available_slots + 1 WHERE id = ?
+  `).run(booking.voyage_id);
