+  const updated = db.prepare('SELECT * FROM bookings WHERE id = ?').get(req.params.id);
+  res.json({
+    message: `Status advanced to "${nextStatus}"`,
+    previous_status: booking.current_status,
+    new_status: nextStatus,
+    booking: updated,
+  });
+});
