          </div>
        </div>

        {/* ── Section: Cargo Details ── */}
        <SectionHeading title="Cargo Details" />
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">

          {/* Cargo Description */}
          <div className="sm:col-span-2">
            <label className="block text-xs font-medium text-gray-700 mb-1">
