      voyage_id: Number(form.voyage_id),
      container_type: form.container_type,
      cargo_description: form.cargo_description,
      gross_weight: parseFloat(form.gross_weight),
      weight_unit: form.weight_unit,
      hazmat: form.hazmat === 'yes',
