      err ? 'border-red-400 bg-red-50' : 'border-gray-300 bg-white'
    } ${isReadOnly ? 'bg-gray-50 text-gray-600 cursor-default' : ''}`
  }

  function FieldError({ msg }: { msg?: string }) {
