6 | // ─────────────────────────────────────────────
7 | // Status lifecycle pipeline (Section 1.3)
8 | // ─────────────────────────────────────────────
9 | const LIFECYCLE = [
10 |   'Booking Confirmed',
11 |   'Documentation Submitted',
12 |   'Gated In (Origin)',
13 |   'Loaded on Vessel',
14 |   'Departed Origin Port',
15 |   'At Sea',
16 |   'Arrived Destination Port',
17 |   'Customs Cleared',
18 |   'Available for Pickup',
19 |   'Delivered',
20 | ];
