22 | // Cutoff rule: edit/cancel allowed only if:
23 | //   1. voyage ETD is in the future AND
24 | //   2. current_status is at or before "Gated In (Origin)" (index 2)
25 | const CUTOFF_STATUS_INDEX = LIFECYCLE.indexOf('Gated In (Origin)'); // 2
26 | 
27 | function checkCutoff(booking: any, voyage: any): { allowed: boolean; reason?: string } {
28 |   const now = new Date();
29 |   const etd = new Date(voyage.etd);
30 |   if (etd <= now) {
31 |     return { allowed: false, reason: `Voyage ETD (${voyage.etd}) has already passed` };
32 |   }
33 |   const statusIdx = LIFECYCLE.indexOf(booking.current_status);
34 |   if (statusIdx > CUTOFF_STATUS_INDEX) {
35 |     return {
36 |       allowed: false,
37 |       reason: `Booking status "${booking.current_status}" is past the edit/cancel cutoff ("Gated In (Origin)")`,
38 |     };
39 |   }
40 |   return { allowed: true };
41 | }
