47 | /** Auto-generate booking number BKG-YYYY-NNNN */
48 | function generateBookingNumber(): string {
49 |   const year = new Date().getFullYear();
50 |   const row = db
51 |     .prepare(`SELECT COUNT(*) AS cnt FROM bookings WHERE booking_number LIKE ?`)
52 |     .get(`BKG-${year}-%`) as { cnt: number };
53 |   const seq = String(row.cnt + 1).padStart(4, '0');
54 |   return `BKG-${year}-${seq}`;
55 | }
56 | 
57 | /** Auto-generate ISO 6346-style container number.
58 |  *  Format: XXXX NNNNNN C  (owner 4-alpha + 6-digit serial + 1-digit check)
59 |  *  We use a simplified but realistic-looking format: SWRE + 6 digits + check digit 0–9
60 |  */
61 | function generateContainerNumber(): string {
62 |   const serial = String(Math.floor(Math.random() * 900000) + 100000);
63 |   const check = String(Math.floor(Math.random() * 10));
64 |   return `SWRE${serial}${check}`;
65 | }
