51 |     .prepare(`SELECT COUNT(*) AS cnt FROM bookings WHERE booking_number LIKE ?`)
52 |     .get(`BKG-${year}-%`) as { cnt: number };
53 |   const seq = String(row.cnt + 1).padStart(4, '0');
54 |   return `BKG-${year}-${seq}`;
