27 | function checkCutoff(booking: any, voyage: any): { allowed: boolean; reason?: string } {
28 |   const now = new Date();
29 |   const etd = new Date(voyage.etd);
30 |   if (etd <= now) {
31 |     return { allowed: false, reason: `Voyage ETD (${voyage.etd}) has already passed` };
32 |   }
33 |   const statusIdx = LIFECYCLE.indexOf(booking.current_status);
34 |   if (statusIdx > CUTOFF_STATUS_INDEX) {
35 |     return {
36 |       allowed: false,
